function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function renderSummary(){$('#navCurrent').textContent='第'+(state.q+1)+'题 / 共'+QUESTIONS.length+'题';const n=steps.flat().filter(s=>state.passed[s.id]).length;$('#score').innerHTML=scoreForCount(n)+' <small>/ '+maxScore+'</small>';$('#meter').style.width=(n/totalSteps*100)+'%';$('#badge').textContent=n===totalSteps?'全部25题完成！每一次思考都算数。':n>=10?'已获得「遗传小导师」，继续完成后续题目。':n>=5?'已获得「推理达人」，继续向满分前进。':n>=1?'已点亮「探索之星」，继续加油。':'每掌握一步，都有新的进步。';$('#badges').innerHTML=[['★',1,'探索之星'],['✦',5,'推理达人'],['♛',10,'遗传小导师']].map(([s,min,t])=>`<span title="${t}" aria-label="${t}${n>=min?' 已获得':' 未获得'}" class="${n>=min?'':'off'}">${s}</span>`).join('');const navScroll=$('#nav').scrollTop;$('#nav').innerHTML=titles.map((t,i)=>{const done=steps[i].filter(s=>state.passed[s.id]).length;const completed=done===steps[i].length;const started=steps[i].some(s=>state.submitted[s.id]);const status=completed?'已完成':started?'作答中':'待作答';return `<button class="navitem ${i===state.q?'active':''} ${completed?'finished':''}" aria-current="${i===state.q?'step':'false'}" aria-label="第${i+1}题，${t}，${status}" data-q="${i}"><b>第${i+1}题</b><span class="nav-status">${status}</span></button>`}).join('');$('#nav').scrollTop=navScroll;$('#done').textContent=steps[state.q].filter(s=>state.passed[s.id]).length+' / '+steps[state.q].length+' 步';$('#finish').innerHTML=n===totalSteps?`<div class="complete"><h2>♛ 全部25题完成 · 遗传小导师</h2><p>你已获得 ${maxScore} 分。可以返回任意题，重新听老师的推理过程。</p></div>`:''}
function contentMarkup(c){if(c.table)return '<div class="question-table"><table>'+c.table.map((row,i)=>'<tr>'+row.map(v=>`<${i?'td':'th'}>${esc(bioText(v))}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';return (c.text?'<p>'+esc(bioText(c.text))+'</p>':'')+(c.images||[]).map(img=>figure(img,'第'+(state.q+1)+'题原题图')).join('')}

function figure(file,label){return `<div class="figures"><img src="${file}" alt="${esc(label)}"></div>`}
function stepContext(s){const c=QUESTIONS[3].content;if(s.id==='q4b')return `<p class="step-context">${esc(bioText(c[2].text.replace(/^\(2\)/,'').split('造成此现象')[0]))}</p>${figure(c[3].images[0],'图1：基因插入片段与引物位置')}`;if(s.id==='q4c')return `<p class="step-context">${esc(bioText(c[4].text))}</p>${figure(c[5].images[0],'图2：甲乙丙的电泳结果')}`;if(s.id==='q4e')return figure(c[5].images[0],'参照原图补充乙和丙的条带');return ''}
function stepBody(s,i){const unlocked=!!state.submitted[s.id];return `${stepContext(s)}<h3>${steps[state.q].length>1?`<small>第 ${i+1} 步</small>`:''}${s.name}</h3>${controls(s)}<div class="actions"><button data-check="${s.id}">${unlocked?'再次提交':'提交答案'}</button><button class="hintbutton" data-explain="${s.id}" ${unlocked?'':'disabled'} aria-expanded="${unlocked&&!!state.open[s.id]}">${unlocked?(state.open[s.id]?'收起解析':'查看分步解析'):'提交后可看解析'}</button></div><div class="result" role="status">${state.passed[s.id]?'<div class="feedback good">✓ 这一步已答对 · 已计入总分</div>':''}</div><div class="explanation">${unlocked&&state.open[s.id]?explain(s):''}</div>`}
function renderKnowledge(){const ready=steps[state.q].every(s=>state.submitted[s.id]);$('#knowledge').innerHTML=ready?knowledgeCard(state.q):'<p class="knowledge-locked">完成本题作答后，解锁课本知识联动。</p>'}
function render(){stopAllVisuals();paused=false;$('#pause').textContent='暂停计时';document.querySelectorAll('audio').forEach(a=>a.pause());const q=QUESTIONS[state.q];$('#chapter').textContent=q.chapter;$('#title').textContent='第'+(state.q+1)+'题 · '+titles[state.q];$('#counter').textContent=steps[state.q].length>1?'综合题 · '+steps[state.q].length+'个步骤':steps[state.q][0].type==='multi'?'不定项选择题':'单项选择题';const before=q.content.slice(0,q.content.findIndex(c=>c.text.startsWith('【答案】')));$('#question').innerHTML=(state.q===3?before.slice(0,1):before).map(c=>/^[ABCD]．/.test(c.text)?'':contentMarkup(c)).join('');$('#steps').innerHTML=steps[state.q].map((s,i)=>`<article class="step" id="step-${s.id}">${stepBody(s,i)}</article>`).join('');renderKnowledge();$('#prev').disabled=state.q===0;$('#next').disabled=state.q===QUESTIONS.length-1;renderSummary();renderClock();save()}
const AUDIO_FILES={...EXT_AUDIO_FILES,"q1-0": "q1-0-v4b.mp3", "q1-1": "q1-1-v4.mp3", "q1-2": "q1-2-v4.mp3", "concept-division": "concept-division-v4.mp3", "concept-count": "concept-count-v4.mp3", "concept-segregation": "concept-segregation-phrasing-edbdea6c0b.mp3",...REVIEW_AUDIO_FILES};
function voicePlayer(id,label='听老师讲解'){const narration=NARRATION_INDEX[id];const filename=narration?.file||AUDIO_FILES[id]||id+'-v3.mp3';return `<div class="teacher-audio"><div><span class="teacher-mark">声</span><b>${label}</b></div><audio controls preload="none" src="audio/${filename}" aria-label="${label}"></audio>${narration?`<details class="narration-transcript"><summary>查看本段语音对应文字</summary><p>${esc(narration.text)}</p></details>`:""}</div>`}
function conceptCard(id){const c=CONCEPTS[id];return `<details class="linked-concept"><summary><span>关联知识</span><b>${esc(c[0])}</b><em>点击展开 ＋</em></summary><div class="concept-body">${voicePlayer('concept-'+id,'听老师讲这个知识点')}<h5>概念是什么</h5><p>${esc(c[1])}</p><h5>如何理解和应用</h5><p>${esc(c[2])}</p><div class="concept-takeaway">记住：${esc(c[3])}</div></div></details>`}
function reasoningMarkup(text){const value=String(text??'');const parts=value.split(/(?:^|\n)\s*[①②③④⑤⑥⑦⑧⑨⑩]\s*/).map(s=>s.trim()).filter(Boolean);return parts.length>1?'<ol class="derivation-steps">'+parts.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ol>':'<p>'+esc(value)+'</p>'}
function optionCard(s,i){const c=OPTION_INSIGHTS[s.id]?.[i],d=DEEP_OPTIONS[s.id]?.[i];if(!c||!d)return '';const correct=s.answer.includes('ABCD'[i]);return `<details class="option-card"><summary><span>${correct?'✓ 本题应选':'辨析 '+ 'ABCD'[i]}</span>${esc(c[0])}</summary><div class="option-card-body">${voicePlayer(s.id+'-'+i,'听老师解析选项'+ 'ABCD'[i])}<div class="reasoning-chain">${['题目依据','推理过程','得出结论'].map((t,j)=>`<section><h5><span>${j+1}</span>${t}</h5>${reasoningMarkup(d[j])}</section>`).join('')}</div><details class="diagram-fold"><summary>看图理解 · 分步推演</summary>${stepVisual(s)}</details>${conceptCard(d[3])}</div></details>`}
function controls(s){const a=state.answers[s.id];if(s.type==='choice'||s.type==='multi')return (s.type==='multi'?'<p class="multi-note">多选题：可选择多个选项，再次点击可取消；全部选对后计分。</p>':'')+'<div class="options">'+s.options.map((o,i)=>`<div class="option-wrap"><button class="option ${(a||'').includes('ABCD'[i])?'selected':''}" data-answer="${s.id}" data-value="${'ABCD'[i]}" aria-pressed="${(a||'').includes('ABCD'[i])}"><b>${'ABCD'[i]}</b><span>${esc(bioText(o))}${s.id==='q2'?`<img class="option-diagram" src="${QUESTIONS[1].content[1].images[i]}" alt="选项${'ABCD'[i]}细胞分裂图">`:''}</span></button>${state.submitted[s.id]?`<div class="option-notes">${optionCard(s,i)}</div>`:''}</div>`).join('')+'</div>';if(s.type==='input')return `<div class="inputwrap"><input type="text" data-input="${s.id}" value="${esc(a||'')}" placeholder="${s.placeholder}" aria-label="${esc(s.name)}" autocomplete="off"></div>`;return `<p class="gelkey">上方＝长片段，靠近点样孔；下方＝短片段。点击条带位置涂黑或取消。</p><div class="gel"><div class="lane"><span>甲（参照）</span><span class="band on">━━</span><span class="band on">━━</span></div>${['乙','丙'].map((label,k)=>`<div class="lane"><span>${label}</span>${[0,1].map(j=>`<button class="band ${(a||'0000')[k*2+j]==='1'?'on':''}" data-band="${s.id}" data-index="${k*2+j}" aria-label="${label}${j?'下':'上'}条带" aria-pressed="${(a||'0000')[k*2+j]==='1'}">${(a||'0000')[k*2+j]==='1'?'━━':'＋'}</button>`).join('')}</div>`).join('')}</div>`}
function knowledgeCard(q){const ids=[['division','count','segregation','gametes'],['recombination','segregation'],['ratio'],['segregation','expression','pcr','electrophoresis'],['alleles','conditional']][q]||EXTRA_KNOWLEDGE[q+1];return `<details class="knowledge-card"><summary><span class="book-icon">书</span><span><small>课本知识联动</small><b>本题涉及的 ${ids.length} 个知识点</b></span><span class="expand-label">点击查看 ＋</span></summary><div class="knowledge-body"><p class="muted">选择需要复习的概念，再展开阅读或听讲解。</p>${ids.map(conceptCard).join('')}<small class="muted">按高中生物课程知识主题整理；不对应某一教材版本的固定页码。</small></div></details>`}
function baseExplain(s){if(typeof DETAILED_FILLS!=='undefined'&&DETAILED_FILLS[s.id]){const concept=EXTRA_STEP_DETAILS[s.id]?.concept||DEEP_STEPS[s.id]?.[3];return '<div class="explain">'+voicePlayer('step-'+s.id,'听老师讲这一步')+'<h4>逐步推导</h4>'+reasoningMarkup(DETAILED_FILLS[s.id])+'</div>'+(concept?conceptCard(concept):'')}if(EXTRA_STEP_DETAILS[s.id]){const d=EXTRA_STEP_DETAILS[s.id];if(DEEP_OPTIONS[s.id])return '<h4>逐项辨析 · 各选项分别讲解</h4>'+DEEP_OPTIONS[s.id].map((_,i)=>optionCard(s,i)).join('');return '<div class="explain">'+voicePlayer('step-'+s.id,'听老师讲这一步')+'<h4>推理过程</h4><p>'+esc(REVIEW_FILL[s.id])+'</p></div>'+conceptCard(d.concept)}if(EXTRA_LESSONS[state.q+1]&&steps[state.q].length===1)return lessonMarkup(EXTRA_LESSONS[state.q+1])+'<h4>逐项辨析</h4>'+DEEP_OPTIONS[s.id].map((_,i)=>optionCard(s,i)).join('');if(DEEP_OPTIONS[s.id])return `<div class="explain"><h4>逐项辨析 · 选择一个选项听老师讲解</h4>${DEEP_OPTIONS[s.id].map((_,i)=>optionCard(s,i)).join('')}</div>`;if(DEEP_STEPS[s.id]){const d=DEEP_STEPS[s.id];return `<div class="explain">${voicePlayer('step-'+s.id,'听老师讲这一步')}<div class="reasoning-chain">${['题目依据','推理过程','得出结论'].map((t,j)=>`<section><h5>${t}</h5>${reasoningMarkup(d[j])}</section>`).join('')}</div>${conceptCard(d[3])}</div>`}let list=s.lessons;if(s.id==='q4b')list=[9];return (s.hint?`<div class="explain"><h4>推理提示</h4><p>${esc(s.hint)}</p></div>`:'')+list.map(i=>{const l=LESSONS[i];return `<div class="explain"><h4>${esc(l.heading)}</h4><div class="formula">${esc(l.formula)}</div><ul>${l.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><div class="voice-label">点击播放讲解</div><audio controls preload="none" src="${l.file}"></audio><details><summary>查看讲解文字</summary><p>${esc(l.voice)}</p></details></div>`}).join('')}
function stepVisual(s){const q=+s.id.match(/^q(\d+)/)[1];if(steps[q-1].every(x=>state.submitted[x.id]))return visualLesson(q);return `<p class="knowledge-locked" data-visual-locked-q="${q}">完成本题各小问作答后，解锁整题分步图解。当前步骤的推理见下方解析。</p>`}
function refreshUnlockedVisuals(q){if(steps[q-1].every(s=>state.submitted[s.id]))document.querySelectorAll('[data-visual-locked-q="'+q+'"]').forEach(n=>{n.outerHTML=visualLesson(q)})}
function explain(s){return stepVisual(s)+baseExplain(s)}
function lessonMarkup(list){return list.map(l=>`<section class="explain"><h4>${esc(l.heading)}</h4><div class="formula">${esc(l.formula)}</div>${voicePlayer('lesson-'+l.id)}<ol>${l.notes.map(n=>'<li>'+esc(n)+'</li>').join('')}</ol></section>`).join('')}
function normalizedAnswer(s,raw){let a=String(raw).trim().replace(/[：∶]/g,':').replace(/[／]/g,'/').replace(/\s/g,'');if(s.type==='multi')return [...new Set(a.toUpperCase().split(''))].sort().join('');if(s.normalize==='text')a=a.toUpperCase();const accepted=[s.answer,...(s.aliases||[])];return accepted.some(v=>(s.normalize==='text'?v.toUpperCase():v)===a)?s.answer:a}
function selectAnswer(s,value){if(s.type==='multi'){const chosen=new Set((state.answers[s.id]||'').split(''));chosen.has(value)?chosen.delete(value):chosen.add(value);state.answers[s.id]=[...chosen].sort().join('')}else state.answers[s.id]=value}
function findStep(id){return steps.flat().find(s=>s.id===id)}
function check(id){const s=findStep(id),raw=state.answers[id]||'';if(!raw.trim()||(s.type==='gel'&&raw==='0000')){notify('先填写或点选你的答案');return}const a=normalizedAnswer(s,raw);let good=a===s.answer;const already=!!state.passed[id];state.submitted[id]=true;if(good&&!already){state.passed[id]=true;notify('★ 分数已更新 · 又掌握了一个知识点')}save();document.querySelectorAll('#step-'+id+' audio').forEach(a=>a.pause());$('#step-'+id).innerHTML=stepBody(s,steps[state.q].indexOf(s));$('#step-'+id+' .result').innerHTML=`<div class="feedback ${good?'good':'bad'}">${good?'✓ 答对了！'+(already?'本步骤已得分，不重复计分。':' 已计入总分，继续保持！'):'答案还不正确，解析已解锁。看看推理过程，再试一次；答错不扣分。'}</div>`;refreshUnlockedVisuals(state.q+1);renderKnowledge();renderSummary()}
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-q]');if(b){state.q=+b.dataset.q;$('#questionNav').open=false;render();$('#questionNavToggle').focus?.();window.scrollTo({top:0,behavior:'smooth'})}});
$('#steps').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.answer){selectAnswer(findStep(b.dataset.answer),b.dataset.value);$('#step-'+b.dataset.answer).querySelectorAll('[data-answer]').forEach(n=>{const selected=(state.answers[b.dataset.answer]||'').includes(n.dataset.value);n.classList.toggle('selected',selected);n.setAttribute('aria-pressed',selected)});$('#step-'+b.dataset.answer+' .result').innerHTML='';save()}if(b.dataset.band){let a=(state.answers[b.dataset.band]||'0000').split('');a[+b.dataset.index]=a[+b.dataset.index]==='1'?'0':'1';state.answers[b.dataset.band]=a.join('');b.classList.toggle('on',a[+b.dataset.index]==='1');b.textContent=a[+b.dataset.index]==='1'?'━━':'＋';b.setAttribute('aria-pressed',a[+b.dataset.index]==='1');save()}if(b.dataset.check)check(b.dataset.check);if(b.dataset.explain){let id=b.dataset.explain;if(!state.submitted[id])return;state.open[id]=!state.open[id];$('#step-'+id+' .explanation').innerHTML=state.open[id]?explain(findStep(id)):'';b.textContent=state.open[id]?'收起解析':'查看分步解析';b.setAttribute('aria-expanded',!!state.open[id]);if(state.open[id])openComparison(id,explain(findStep(id)));save()}});
$('#steps').addEventListener('input',e=>{if(e.target.dataset.input){state.answers[e.target.dataset.input]=e.target.value;save()}});$('#steps').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.input)check(e.target.dataset.input)});
document.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'&&!e.target.open)e.target.querySelectorAll('audio').forEach(a=>a.pause())},true);
document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})},true);document.addEventListener('error',e=>{if(e.target.tagName==='AUDIO')notify('音频暂时无法播放，请先阅读下方讲解文字。')},true);
function move(n){state.q=Math.max(0,Math.min(QUESTIONS.length-1,state.q+n));render();window.scrollTo({top:0,behavior:'smooth'})}$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'继续计时':'暂停计时'};
function renderClock(){let t=state.times[state.q]||0;$('#clock').textContent=`学习计时 ${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}
setInterval(()=>{if(!paused&&!document.hidden){state.times[state.q]++;renderClock();save()}},1000);$('#reset').onclick=()=>$('#resetdialog').showModal();$('#cancelreset').onclick=()=>$('#resetdialog').close();$('#confirmreset').onclick=()=>{state={version:1,q:0,answers:{},passed:{},open:{},submitted:{},times:Array(QUESTIONS.length).fill(0)};paused=false;$('#pause').textContent='暂停计时';$('#resetdialog').close();save();render()};
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'navigate_biology_question',description:'打开25道生物练习中的指定题目，不提交答案。',inputSchema:{type:'object',properties:{number:{type:'integer',minimum:1,maximum:25}},required:['number'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({number})=>{if(!Number.isInteger(number)||number<1||number>25)throw Error('题号须为1至25');state.q=number-1;render();return {question:number,title:titles[state.q]}}})}
render();

const profileKey='biology-profile-v1';let studentProfile={className:'',name:''};try{const p=JSON.parse(localStorage.getItem(profileKey));if(p&&typeof p.className==='string'&&typeof p.name==='string')studentProfile={className:p.className.slice(0,30),name:p.name.slice(0,20)}}catch{}
let awardSnapshot=null;
function awardData(){const count=steps.flat().filter(s=>state.passed[s.id]).length;return {count,score:scoreForCount(count),title:count>=10?'遗传小导师':count>=5?'推理达人':count>=1?'探索之星':null}}
function awardSaveProfile(){studentProfile={className:$('#awardClass').value.trim().slice(0,30),name:$('#awardName').value.trim().slice(0,20)};try{localStorage.setItem(profileKey,JSON.stringify(studentProfile))}catch{}awardSnapshot=null;$('#awardPreview').hidden=true}
function drawAward(data){const canvas=$('#awardCanvas'),c=canvas.getContext('2d');if(!c)throw Error('当前浏览器暂不支持图片生成');const W=2480,H=1748;c.clearRect(0,0,W,H);c.fillStyle='#fffdf7';c.fillRect(0,0,W,H);c.strokeStyle='#24477c';c.lineWidth=7;c.strokeRect(62,62,W-124,H-124);c.strokeStyle='#cba04c';c.lineWidth=2;c.strokeRect(88,88,W-176,H-176);c.fillStyle='#24477c';c.fillRect(88,88,W-176,16);
 const text=(value,y,size,color='#243e64',weight=400,maxWidth=2100)=>{c.font=`${weight} ${size}px "PingFang SC","Microsoft YaHei",sans-serif`;while(c.measureText(value).width>maxWidth&&size>22){size-=2;c.font=`${weight} ${size}px "PingFang SC","Microsoft YaHei",sans-serif`}c.fillStyle=color;c.textAlign='center';c.textBaseline='middle';c.fillText(value,W/2,y)};
 text('生物研习室  /  学习成就卡',225,44,'#5c6d82',500);text('中秋假期生物作业 · 全25题',327,56,'#243e64',500);c.strokeStyle='#cba04c';c.beginPath();c.moveTo(930,402);c.lineTo(1550,402);c.stroke();text(data.title,570,150,'#24477c',700);text(data.name+' 同学',805,92,'#243e64',600);text(data.className,931,57,'#61708a',400);text('在本次生物自主练习中，获得以下学习记录',1070,45,'#5c6d82');text(`累计积分 ${data.score} / ${maxScore}     ·     累计答对 ${data.count} / ${totalSteps} 个步骤`,1190,57,'#243e64',600);text(data.count===totalSteps?'完成全套练习，让理解成为自己的力量。':'每一次思考与订正，都让理解更进一步。',1320,46,'#6d5a31');text('生成日期：'+data.date,1490,35,'#667387');text('自主练习记录 · 包含订正后的答对结果',1550,30,'#78808c');canvas.setAttribute('aria-label',`${data.className} ${data.name}，${data.title}，${data.score}分`);return canvas}
$('#openAward').onclick=()=>{const d=awardData();$('#awardClass').value=studentProfile.className;$('#awardName').value=studentProfile.name;$('#awardEligibility').textContent=d.title?`当前称号：${d.title} · ${d.score} 分`:'先答对至少一个步骤，即可生成学习成就卡。';$('#generateAward').disabled=!d.title;$('#awardPreview').hidden=true;awardSnapshot=null;$('#awardDialog').showModal()};
$('#closeAward').onclick=()=>$('#awardDialog').close();$('#awardClass').addEventListener('input',awardSaveProfile);$('#awardName').addEventListener('input',awardSaveProfile);
$('#awardForm').addEventListener('submit',async e=>{e.preventDefault();awardSaveProfile();const d=awardData();if(!studentProfile.name||!studentProfile.className){notify('请填写班级和姓名');return}if(!d.title){notify('先答对一个步骤，再来领取称号');return}try{if(document.fonts?.ready)await document.fonts.ready;const now=new Date();const snapshot={...d,...studentProfile,date:`${now.getFullYear()}年${now.getMonth()+1}月${now.getDate()}日`};drawAward(snapshot);awardSnapshot=snapshot;$('#awardCaption').textContent=`${snapshot.className} · ${snapshot.name} · ${snapshot.title} · ${snapshot.score}分`;$('#awardPreview').hidden=false}catch(err){notify('图片生成失败，请换用支持绘图的浏览器重试。')}});
$('#downloadAward').onclick=()=>{if(!awardSnapshot)return;const snapshot=awardSnapshot;try{$('#awardCanvas').toBlob(blob=>{if(!blob){notify('图片生成失败，请重试');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${snapshot.className}_${snapshot.name}_学习成就卡_${snapshot.title}.png`.replace(/[\\/:*?"<>|]/g,'_');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)},'image/png')}catch{notify('浏览器未能下载图片，可尝试打印并保存为PDF。')}};
$('#printAward').onclick=async()=>{if(!awardSnapshot)return;const img=$('#awardPrintImage');img.src=$('#awardCanvas').toDataURL('image/png');try{await img.decode();window.print()}catch{notify('打印预览尚未准备好，请重试')}};

// Keep the source question and its explanation visible in independently scrolling panes.
function openComparison(stepId,html){stopAllVisuals();
 const step=steps[state.q].find(s=>s.id===stepId);
 if(stepId?(!step||!state.submitted[stepId]):!steps[state.q].every(s=>state.submitted[s.id]))return;
 document.querySelectorAll('audio').forEach(a=>a.pause());
 const contents=QUESTIONS[state.q].content;const end=contents.findIndex(c=>c.text.startsWith('【答案】'));
 $('#comparisonQuestion').innerHTML=contents.slice(0,end<0?contents.length:end).map(contentMarkup).join('');
 $('#comparisonExplanation').innerHTML=(step?'<p class="comparison-step">'+esc(step.name)+'</p>':'')+html;
 $('#comparisonTitle').textContent='第'+(state.q+1)+'题 · 题目对照';
 $('#comparisonQuestion').scrollTop=0;$('#comparisonExplanation').scrollTop=0;
 if(!$('#comparisonDialog').open)$('#comparisonDialog').showModal();
}
$('#closeComparison').onclick=()=>$('#comparisonDialog').close();
$('#comparisonDialog').addEventListener('close',()=>{stopAllVisuals();$('#comparisonDialog').querySelectorAll('audio').forEach(a=>a.pause());$('#comparisonExplanation').innerHTML=''});
document.addEventListener('toggle',e=>{
 const card=e.target;
 if(card.tagName!=='DETAILS'||!card.open||card.closest('#comparisonDialog'))return;
 if(!card.matches('.option-card,.linked-concept,.knowledge-card'))return;
 const step=card.closest('.step');
 if(step)openComparison(step.id.replace('step-',''),card.outerHTML);
 else if(card.closest('#knowledge'))openComparison(null,card.outerHTML);
},true);
